public class RenoSimulator {
    enum State { SLOW_START, CONGESTION_AVOIDANCE, FAST_RECOVERY }

    private double cwnd = 10.0;      // unit: MSS, IW10
    private double ssthresh = 16.0;  // lowered so the demo reaches CA quickly
    private State state = State.SLOW_START;
    private int dupAckCount = 0;

    public static void main(String[] args) {
        RenoSimulator tcp = new RenoSimulator();
        tcp.print("init");
        for (int i = 1; i <= 8; i++) tcp.onNewAck("new ACK " + i);
        tcp.onDupAck("dupACK 1");
        tcp.onDupAck("dupACK 2");
        tcp.onDupAck("dupACK 3 -> fast retransmit");
        tcp.onDupAck("dupACK 4 in fast recovery");
        tcp.onNewAck("new ACK exits fast recovery");
        tcp.onRto("RTO timeout");
    }

    void onNewAck(String event) {
        if (state == State.SLOW_START) {
            cwnd += 1.0;
            if (cwnd >= ssthresh) state = State.CONGESTION_AVOIDANCE;
        } else if (state == State.CONGESTION_AVOIDANCE) {
            cwnd += 1.0 / cwnd;  // MSS²/cwnd, 累计一个 RTT 约 +1 MSS
        } else { // FAST_RECOVERY
            cwnd = ssthresh;
            state = State.CONGESTION_AVOIDANCE;
        }
        dupAckCount = 0;
        print(event);
    }

    void onDupAck(String event) {
        dupAckCount++;
        if (state == State.FAST_RECOVERY) {
            cwnd += 1.0;  // 维持管道
            print(event);
            return;
        }
        if (dupAckCount == 3) {
            ssthresh = Math.max(cwnd / 2.0, 2.0);  // 乘性减
            cwnd = ssthresh + 3.0;  // 3 段已离开网络
            state = State.FAST_RECOVERY;
        }
        print(event);
    }

    void onRto(String event) {
        ssthresh = Math.max(cwnd / 2.0, 2.0);
        cwnd = 1.0;  // loss window, 退回慢启动
        state = State.SLOW_START;
        dupAckCount = 0;
        print(event);
    }

    void print(String event) {
        System.out.printf("%-36s state=%-22s cwnd=%5.2f MSS ssthresh=%5.2f dupACK=%d%n",
                event, state, cwnd, ssthresh, dupAckCount);
    }
}
